use zorid_document::{parse_markdown_facts, BlockKind, ParseFacts, SourceRange, SCHEMA_VERSION};

// Expected intervals are literal reviewed source fragments, never generated by
// a second parser or copied from candidate metadata. Coordinates include the BOM,
// CRLF and astral scalars from the original input.
fn exact(source: &str, actual: &SourceRange, expected: &str) {
    let start = source
        .find(expected)
        .expect("unique expected source fragment");
    assert!(
        source[start + expected.len()..].find(expected).is_none(),
        "ambiguous fixture"
    );
    let end = start + expected.len();
    assert_eq!(actual.bytes, [start as u32, end as u32], "{expected:?}");
    assert_eq!(
        actual.utf16,
        [
            source[..start].encode_utf16().count() as u32,
            source[..end].encode_utf16().count() as u32
        ],
        "{expected:?}"
    );
    assert_eq!(
        &source[actual.bytes[0] as usize..actual.bytes[1] as usize],
        expected
    );
}

#[test]
fn maximal_non_list_blocks_use_actual_parser_extents_in_original_source() {
    let source = "\u{feff}---\r\ntitle: ignored\r\n---\r\n# Heading 😀\r\n\r\nparagraph α\r\ncontinues\r\n\r\n> quote one\r\n>\r\n> quote two\r\n\r\n```\r\n- [x] hidden\r\n```\r\n\r\n<div>\r\n- [ ] html\r\n</div>\r\n\r\n| A | B |\r\n| - | - |\r\n| 1 | 2 |\r\n\r\n***\r\n";
    let facts = parse_markdown_facts(source).unwrap();
    assert_eq!(facts.schema_version, 2);
    assert_eq!(SCHEMA_VERSION, 2);
    let expected = [
        (BlockKind::Heading, "# Heading 😀"),
        (BlockKind::Paragraph, "paragraph α\r\ncontinues"),
        (BlockKind::Blockquote, "> quote one\r\n>\r\n> quote two"),
        (BlockKind::Code, "```\r\n- [x] hidden\r\n```"),
        (BlockKind::Html, "<div>\r\n- [ ] html\r\n</div>"),
        (BlockKind::Table, "| A | B |\r\n| - | - |\r\n| 1 | 2 |"),
        (BlockKind::ThematicBreak, "***"),
    ];
    assert_eq!(facts.blocks.len(), expected.len());
    for (block, (kind, fragment)) in facts.blocks.iter().zip(expected) {
        assert_eq!(block.kind, kind);
        exact(source, &block.range, fragment);
    }
    assert!(facts.list_items.is_empty());
    assert!(
        facts.tasks.is_empty(),
        "frontmatter/code/HTML do not create tasks"
    );
}

#[test]
fn full_items_include_multiline_descendants_without_reinterpreting_task_ranges() {
    let source = "😀 prefix\r\n\r\n- [ ] parent 😀\r\n  continuation α\r\n  - [x] child\r\n    child continuation\r\n- [!] sibling\r\n- ordinary item\r\n";
    let facts = parse_markdown_facts(source).unwrap();
    let fragments = [
        "- [ ] parent 😀\r\n  continuation α\r\n  - [x] child\r\n    child continuation",
        "- [x] child\r\n    child continuation",
        "- [!] sibling",
        "- ordinary item",
    ];
    assert_eq!(facts.list_items.len(), 4);
    assert_eq!(facts.tasks.len(), 3);
    assert_eq!(
        facts.blocks.len(),
        1,
        "list container and child paragraphs are not blocks"
    );
    exact(source, &facts.blocks[0].range, "😀 prefix");
    for (item, fragment) in facts.list_items.iter().zip(fragments) {
        exact(source, &item.range, fragment);
    }
    for (n, (status, label)) in [(" ", "parent 😀"), ("x", "child"), ("!", "sibling")]
        .into_iter()
        .enumerate()
    {
        let task = &facts.tasks[n];
        assert_eq!(task.status, status);
        assert_eq!(facts.list_items[n].task_status.as_deref(), Some(status));
        assert_eq!(task.item_range, facts.list_items[n].range);
        exact(source, &task.range, &format!("[{status}]"));
        let status_start = task.range.bytes[0] as usize + 1;
        assert_eq!(
            task.status_range.bytes,
            [status_start as u32, (status_start + status.len()) as u32]
        );
        assert_eq!(&source[status_start..status_start + status.len()], status);
        let text_start = task.range.bytes[1] as usize + 1;
        let text_end = text_start + label.len();
        assert_eq!(task.text_range.bytes, [text_start as u32, text_end as u32]);
        assert_eq!(
            task.text_range.utf16,
            [
                source[..text_start].encode_utf16().count() as u32,
                source[..text_end].encode_utf16().count() as u32
            ]
        );
        assert_eq!(&source[text_start..text_end], label);
        assert_eq!(task.text, label);
        assert_eq!(task.completed, status == "x");
    }
    assert_eq!(facts.tasks[0].line, 2);
    assert_eq!(facts.tasks[1].line, 4);
    assert_eq!(facts.tasks[2].line, 6);
    assert_eq!(facts.list_items[3].task_status, None);
}

#[test]
fn custom_markers_stay_searchable_but_astral_markers_are_not_checkboxes() {
    let source = "+ [/] active\n* [é] tarea\n1. [-] held\n2. [😀] literal\n";
    let facts = parse_markdown_facts(source).unwrap();
    assert_eq!(facts.list_items.len(), 4);
    assert_eq!(facts.tasks.len(), 3);
    assert_eq!(
        facts
            .tasks
            .iter()
            .map(|task| task.status.as_str())
            .collect::<Vec<_>>(),
        ["/", "é", "-"]
    );
    assert!(facts
        .tasks
        .iter()
        .all(|task| task.checked && !task.completed));
    assert_eq!(facts.list_items[3].task_status, None);
    for task in &facts.tasks {
        assert_eq!(
            task.item_range,
            facts
                .list_items
                .iter()
                .find(|item| item.task_status.as_ref() == Some(&task.status))
                .unwrap()
                .range
        );
        let start = task.range.bytes[0] as usize + 1;
        assert_eq!(
            task.status_range.bytes,
            [start as u32, (start + task.status.len()) as u32]
        );
        assert_eq!(&source[start..start + task.status.len()], task.status);
    }
}

#[test]
fn schema_two_requires_new_fields_and_preserves_closed_frontmatter_exclusion() {
    let source = "---\nvalue: [invalid\n- [x] hidden\n---\n%%- [ ] comment%%\n\n- [ ] visible\n";
    let facts = parse_markdown_facts(source).unwrap();
    assert_eq!(facts.list_items.len(), 1);
    assert_eq!(facts.tasks.len(), 1);
    exact(source, &facts.list_items[0].range, "- [ ] visible");
    let value = serde_json::to_value(&facts).unwrap();
    for field in ["blocks", "listItems"] {
        let mut missing = value.clone();
        missing.as_object_mut().unwrap().remove(field);
        assert!(serde_json::from_value::<ParseFacts>(missing).is_err());
    }
    let mut missing = value;
    missing["tasks"][0]
        .as_object_mut()
        .unwrap()
        .remove("itemRange");
    assert!(serde_json::from_value::<ParseFacts>(missing).is_err());
}
